import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Week 7 — Read It, Debug It","description":"","frontmatter":{"source":"weeks/07-read-and-debug/README.md"},"headers":[],"relativePath":"weeks/07-read-and-debug/index.md","filePath":"weeks/07-read-and-debug/index.md"}'),s={name:"weeks/07-read-and-debug/index.md"};function n(i,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="week-7--read-it-debug-it" tabindex="-1">Week 7 — Read It, Debug It <a class="header-anchor" href="#week-7--read-it-debug-it" aria-label="Permalink to &quot;Week 7 — Read It, Debug It&quot;">​</a></h1><blockquote><p>You must be able to read and fix what the AI wrote.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before Studio A</strong> (30 min at most)</td><td>Read this page and two short sections of <a href="./../../resources/web-basics.html">How the Web Works</a> (about 10 minutes), then the <a href="#before-class">Before class</a> list</td></tr><tr><td><strong>Studio A</strong></td><td>Concept talk and a live debugging demo. Lab: map your own app, find errors a partner plants in it, set up the Debug Clinic. The <strong>exit ticket</strong> is at the end of Studio A this week</td></tr><tr><td><strong>Studio B</strong></td><td>The <strong>Debug Clinic</strong>: five planted bugs, in pairs, with the AI off (about 60 minutes), then a debrief</td></tr><tr><td><strong>Due before next week&#39;s Studio A</strong> (default 11:59 pm the night before)</td><td>Project 1 checked for the clinic&#39;s five bugs (🔴 AI off) · <code>TESTS.md</code> with at least three edge cases · failing MUST criteria fixed · &quot;How it works&quot; drafted · reflection on Canvas. Details: <a href="./homework.html">homework</a></td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: fixing your Project 1 at home (Copilot <strong>Ask</strong> mode or a chat assistant; no agent mode yet) · 🟡 AI limited: tutor mode in the clinic, after 10 minutes stuck on one bug · 🔴 AI off: the studio labs, the Debug Clinic, checking your code for the five bugs, the reflection, the exit ticket</td></tr><tr><td><strong>Must read</strong></td><td>This page, the <a href="./lab.html">lab</a> and the <a href="./homework.html">homework</a></td></tr><tr><td><strong>Look up when needed</strong></td><td>The <a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic/blob/main/README.md" target="_blank" rel="noreferrer">Debug Clinic kit</a> (you read it in the lab) · <a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic/blob/main/hint-cards.md" target="_blank" rel="noreferrer">hint cards</a> · <a href="./../../resources/glossary.html">Glossary</a> · <a href="./../../resources/troubleshooting.html">Troubleshooting</a> · <a href="./../../resources/accessibility.html">Screen reader and keyboard guide</a></td></tr><tr><td><strong>Minimum to keep up</strong></td><td>Your Project 1 runs in its Codespace preview, and you&#39;ve checked it for the five clinic bugs. Week 8 finishes Project 1</td></tr><tr><td><strong>Time</strong></td><td>Studios 2½ h · outside about 5¾ h (prep 30 min, homework core about 2¾ h, project time about 2 h, <code>PROMPTS.md</code> and reflection about 30 min); stretch is optional</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Name the parts of a small web app (structure, style, behavior, state, storage) and find each one in your own files.</li><li>Read a browser error message and a stack trace, and go to the failing line.</li><li>Debug with a method (reproduce → isolate → hypothesize → test → fix → verify) instead of pasting errors into a chat.</li><li>Explain why <code>input.value</code> is text, and how <code>JSON.stringify</code> and <code>JSON.parse</code> save and load data in localStorage.</li><li>Find the edge cases where your own app breaks, and write them down as tests.</li></ol><h2 id="before-class" tabindex="-1">Before class <a class="header-anchor" href="#before-class" aria-label="Permalink to &quot;Before class&quot;">​</a></h2><ul><li>☐ Your Project 1 version 1 is live on GitHub Pages (<a href="./../06-spec-to-app/">week 6</a> homework).</li><li>☐ Stop any codespaces you aren&#39;t using at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>. You&#39;ll run two in Studio A: your Project 1 and the clinic.</li><li>☐ Read &quot;HTML, CSS and JavaScript&quot; and &quot;A short DevTools tour&quot; in <a href="./../../resources/web-basics.html">How the Web Works</a>.</li><li>☐ In your own <code>app.js</code>, find one <code>getElementById</code>, one <code>addEventListener</code> and the <code>localStorage.setItem</code> line.</li></ul><h2 id="studio-agenda" tabindex="-1">Studio agenda <a class="header-anchor" href="#studio-agenda" aria-label="Permalink to &quot;Studio agenda&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Studio</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Studio A — Learn &amp; build</strong></td><td>Recap, concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-07.html" target="_blank" rel="noreferrer">slides</a>) and a live debugging demo. Lab: map your own app, the error drill, set up the clinic. Exit ticket (🔴 AI off)</td></tr><tr><td><strong>Studio B — Workshop</strong></td><td>The <strong>Debug Clinic</strong> (🔴 AI off), then a debrief. No show and tell this week</td></tr></tbody></table><h2 id="materials" tabindex="-1">Materials <a class="header-anchor" href="#materials" aria-label="Permalink to &quot;Materials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td><a href="./lab.html">Lab</a></td><td>Step-by-step, both studios (must read)</td></tr><tr><td><a href="./homework.html">Homework</a></td><td>Deliverables checklist and tasks (must read)</td></tr><tr><td><a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic/blob/main/README.md" target="_blank" rel="noreferrer">Debug Clinic kit</a></td><td>The Reading Log app with five planted bugs, its rules, scoring and <a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic/blob/main/hint-cards.md" target="_blank" rel="noreferrer">hint cards</a></td></tr><tr><td><a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-07.html" target="_blank" rel="noreferrer">Slides</a></td><td>The 15-minute concept talk</td></tr><tr><td><a href="./../../templates/TESTS.html">TESTS template</a></td><td>You extend <code>TESTS.md</code> in the homework</td></tr><tr><td><a href="./../../resources/tutor-mode.html">Tutor mode</a></td><td>The hint-only tutor prompt (🟡 AI limited, in the clinic only)</td></tr></tbody></table><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p>If you&#39;re working through this week on your own, read this section, then do the <a href="./lab.html">lab</a>. The <a href="./../../resources/self-paced.html">self-paced path</a> says what to do instead of the pair activities.</p><p><strong>Why this week exists.</strong> AI helps people finish tasks, but it can stop them learning to debug. In Anthropic&#39;s January 2026 randomized trial, junior engineers who learned a new library with an AI assistant scored 50% on a follow-up quiz, against 67% without it, and the biggest gap was on debugging (<a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">Anthropic</a>). In a 2026 study of 78 learners, 77% of those who had used AI without limits failed a 30-minute maintenance task once the AI was switched off (<a href="https://arxiv.org/abs/2602.20206" target="_blank" rel="noreferrer">Sankaranarayanan</a>). In CMU&#39;s AI coding course, understanding peaked on the assignment where students read and partly wrote the code (<a href="https://www.cs.cmu.edu/~113/bestPractices.html" target="_blank" rel="noreferrer">CMU 15-113</a>). So this week you read and debug, and next week you write, before agents arrive in week 11.</p><p><strong>Anatomy of a web app.</strong> Every app you&#39;ve built so far has five parts. <strong>Structure</strong>: HTML elements such as <code>&lt;button&gt;</code> and <code>&lt;ul&gt;</code>, each of which can have an <strong>id</strong>, a unique name JavaScript uses to find it. JavaScript sees the page as the <strong><a href="./../../resources/glossary.html#dom">DOM</a></strong> (Document Object Model), a live model of the HTML it can read and change. <strong>Style</strong>: CSS, which rarely crashes but can look wrong. <strong>Behavior</strong>: JavaScript functions connected to <strong><a href="./../../resources/glossary.html#event-and-event-listener">events</a></strong> (clicks, typing) with <code>addEventListener</code>. <strong>State</strong>: the data the app is holding right now, in variables, lost on reload. <strong>Storage</strong>: <a href="./../../resources/glossary.html#localstorage">localStorage</a> keeps <strong>text only</strong>, so data goes in with <code>JSON.stringify</code> and comes back out with <code>JSON.parse</code> (like Python&#39;s <code>json.dumps</code> and <code>json.loads</code>). And whatever a user types arrives as text, even in a number box. Python would stop you with a <code>TypeError</code>; JavaScript quietly joins the two: <code>40 + &quot;5&quot;</code> is <code>&quot;405&quot;</code>.</p><p><strong>Read the error before you paste it.</strong> Browser <strong><a href="./../../resources/glossary.html#devtools">DevTools</a></strong> (F12) has a <strong><a href="./../../resources/glossary.html#console">Console</a></strong> that shows errors in red and warnings in yellow. An error has a <a href="./../../resources/glossary.html#syntaxerror-typeerror-and-referenceerror">type</a> (<code>SyntaxError</code>: the file couldn&#39;t be read; <code>TypeError</code>: a value wasn&#39;t what the code expected; <code>ReferenceError</code>: a name doesn&#39;t exist), a message, and a file and line number you can click. A <strong><a href="./../../resources/glossary.html#stack-trace">stack trace</a></strong> lists the chain of function calls. It&#39;s upside down compared with a Python traceback: the <strong>top</strong> line is where it broke, and the lines below are who called it.</p><p><strong>The debugging method.</strong> <strong>Reproduce</strong> (make it happen on purpose), <strong>isolate</strong> (which file, function and line?), <strong>hypothesize</strong> (say what you think is wrong and why), <strong>test</strong> the idea before changing code (type a variable name in the Console, or add <code>console.log</code>), <strong>fix</strong> the cause with the smallest change, and <strong>verify</strong> (repeat the steps and check nothing else broke).</p><p><strong>Bugs live at the edges.</strong> The normal case usually works, because it&#39;s the case the AI was thinking about. <strong><a href="./../../resources/glossary.html#edge-case">Edge cases</a></strong> are the unusual-but-possible ones: empty input, huge input, duplicates, special characters, reloading, a small screen, a first visit with nothing saved. When researchers watched students build with an AI agent, only 2.2% of their checks tried one (<a href="https://arxiv.org/pdf/2507.22614" target="_blank" rel="noreferrer">Geng et al.</a>).</p><h2 id="understanding-check" tabindex="-1">Understanding check <a class="header-anchor" href="#understanding-check" aria-label="Permalink to &quot;Understanding check&quot;">​</a></h2><ul><li><strong>Exit ticket</strong> (🔴 AI off, end of Studio A, graded on completion, not correctness): week 7 questions. One question asks about your week 5 spec, from memory.</li><li><strong>The error drill and the Debug Clinic</strong> (🔴 AI off) are practice for the first of the <a href="./../../resources/without-ai-skills.html#1-read-an-error-message-and-find-the-failing-line">six skills you must show without AI</a>: reading an error message and finding the failing line.</li></ul><p>To check yourself first: open your <code>app.js</code>, point to the line that saves your data and the line that loads it, and explain each in one sentence. Then explain what <code>Cannot read properties of null</code> means and where you&#39;d look first.</p><h2 id="homework" tabindex="-1">Homework <a class="header-anchor" href="#homework" aria-label="Permalink to &quot;Homework&quot;">​</a></h2><p>About 5¼ hours, including project time: the clinic&#39;s five bugs in your own code (🔴 AI off to check), an edge-case hunt recorded in <code>TESTS.md</code>, fixes for failing MUST criteria, a &quot;How it works&quot; draft, and a reflection on Canvas. Details: <a href="./homework.html">homework</a>.</p><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If this fails</th><th>Do this</th></tr></thead><tbody><tr><td>Codespaces won&#39;t start or you&#39;re out of free hours</td><td>Stop your other codespaces at <a href="https://github.com/codespaces" target="_blank" rel="noreferrer">github.com/codespaces</a>, pair in a partner&#39;s codespace, or use <a href="./../../setup/local-setup.html">local setup</a>. The clinic app also runs from a ZIP download: open <code>index.html</code> in a browser</td></tr><tr><td>Tutor mode isn&#39;t available</td><td>Use the hint cards and ask your instructor or TA</td></tr><tr><td>Copilot is unavailable or out of credits (homework)</td><td>Use your chat assistant in a browser tab (<a href="./../../TOOLS.html">Tool Handout</a>)</td></tr><tr><td>GitHub Pages is slow to update</td><td>Check the <strong>Actions</strong> tab</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>MDN, &quot;What went wrong? Troubleshooting JavaScript&quot;: <a href="https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/What_went_wrong" target="_blank" rel="noreferrer">https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Scripting/What_went_wrong</a></li><li>Chrome DevTools, &quot;Debug JavaScript&quot; (breakpoints, stepping through code): <a href="https://developer.chrome.com/docs/devtools/javascript" target="_blank" rel="noreferrer">https://developer.chrome.com/docs/devtools/javascript</a></li><li>The Anthropic study, including the AI-use patterns of high scorers: <a href="https://www.anthropic.com/research/AI-assistance-coding-skills" target="_blank" rel="noreferrer">https://www.anthropic.com/research/AI-assistance-coding-skills</a></li><li><a href="./../../resources/without-ai-skills.html">Six Skills You Must Show Without AI</a>, with practice for each</li></ul>',29)])])}const p=t(s,[["render",n]]);export{g as __pageData,p as default};
